  "codebook": {
    "definition": "Credit-claiming is defined as a politician taking personal or collaborative responsibility for a desirable government action, decision, or the securement of particularized benefits (such as federal grants, projects, localized programs, or legislative provisions) that benefit their constituents, state, or specific target groups.",
    "clarification": "To classify a press release as credit-claiming (1), the text must indicate that the senator has personally undertaken action—such as authoring/sponsoring legislation, introducing amendments, writing advocacy letters, holding hearings, or actively negotiating—to secure a positive result or federal funds. If the senator simply announces a local grant, university award, or military installation improvement, it is coded as credit-claiming if the senator explicitly notes their role, committee membership, or active advocacy in bringing that benefit about.",
    "positive_examples": [
      {
        "document_id": "1862",
        "explanation": "The senators explicitly claim that they 'have delivered on their promise to secure federal funding' and 'went to bat for these dollars,' taking direct responsibility for the local defense project funding."
      },
      {
        "document_id": "2697",
        "explanation": "Senator Inouye describes searching for and successfully securing an alternative federal funding source after the administration rejected his initial request to control the coqui frog population."
      }
    ],
    "negative_clarification": "Do not classify a text as credit-claiming (0) if the senator is merely expressing an opinion, stating a policy position, praising another politician's initiative without noting their own role, issuing symbolic condolences, or criticizing an opponent. Even if the topic involves a desirable outcome, if the senator claims no personal or joint responsibility in achieving it, it is not credit-claiming.",
    "negative_examples": [
      {
        "document_id": "656",
        "explanation": "Senator Kerry's statement is entirely a partisan critique of the Bush Administration's handling of the Dubai Ports deal, containing no claims of personal policy success or legislative achievements."
